            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "I like friends who have independent minds because they tend to make you see problems from all angles.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Only free men can negotiate; prisoners cannot enter into contracts. Your freedom and mine cannot be separated.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "The cause of Communism is the greatest cause in the history of mankind because it seeks to remove from society all forms of oppression and exploitation, to liberate mankind and to ensure peace and prosperity to all.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Experience is the best legacy men could possess and never desert in life.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "I stand here before you not as a prophet but as a humble servant of you, the people. Your tireless and heroic sacrifices have made it possible for me to be here today. I therefore place the remaining years of my life in your hands.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Exercise dissipates tension, and tension is the enemy of serenity. I found that I worked better and thought more clearly when I was in good physical condition, and so training became one of the inflexible disciplines of my life.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "I never think of the time I have lost. I just carry out a programme because it's there. It's mapped out for me.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Death is something inevitable. When a man has done what he considers to be his duty to his people and his country, he can rest in peace. I believe I have made that effort and that is, therefore, why I will sleep for the eternity.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "It is in the character of growth that we should learn from both pleasant and unpleasant experiences.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Real leaders must be ready to sacrifice all for the freedom of their people.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Our march to freedom is irreversible. We must not allow fear to stand in our way. Universal suffrage on a common voters' roll in a united, democratic and non-racial South Africa is the only way to peace and racial harmony.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "The Cuban people hold a special place in the hearts of the people of Africa. The Cuban internationalists have made a contribution to African independence, freedom, and justice, unparalleled for its principled and selfless character.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "We admire the achievements of the Cuban revolution in the sphere of social welfare. We note the transformation from a country of imposed backwardness to universal literacy. We acknowledge your advances in the fields of health, education, and science.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "The life of Che is an inspiration to all human beings who cherish freedom. We will always honour his memory.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "We speak here of the challenge of the dichotomies of war and peace, violence and non-violence, racism and human dignity, oppression and repression and liberty and human rights, poverty and freedom from want.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "This is indeed a joyous night. Although not yet final, we have received the provisional results of the election, and are delighted by the overwhelming support for the African National Congress.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Today we are entering a new era for our country and its people. Today we celebrate not the victory of a party, but a victory for all the people of South Africa.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "The people of South Africa have spoken in these elections. They want change! And change is what they will get. Our plan is to create jobs, promote peace and reconciliation, and to guarantee freedom for all South Africans.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "We speak as fellow citizens to heal the wounds of the past with the intent of constructing a new order based on justice for all.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Out of the experience of an extraordinary human disaster that lasted too long, must be born a society of which all humanity will be proud.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "The time for the healing of the wounds has come. The moment to bridge the chasms that divide us has come. The time to build is upon us.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "We must therefore act together as a united people, for national reconciliation, for nation building, for the birth of a new world. Let there be justice for all. Let there be peace for all.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Never, never and never again shall it be that this beautiful land will again experience the oppression of one by another and suffer the indignity of being the skunk of the world. Let freedom reign!", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "All of us have a role to play in shaping society.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "When a man is denied the right to live the life he believes in, he has no choice but to become an outlaw.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "A good head and a good heart are always a formidable combination.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "I learned that courage was not the absence of fear, but the triumph over it. The brave man is not he who does not feel afraid, but he who conquers that fear.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "In my country we go to prison first and then become President.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "No one truly knows a nation until one has been inside its jails. A nation should not be judged by how it treats its highest citizens but its lowest ones.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "There is nothing like returning to a place that remains unchanged to find the ways in which you yourself have altered.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "You may succeed in delaying, but never in preventing the transition of South Africa to a democracy.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Any man that tries to rob me of my dignity will lose.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "The victory of democracy in South Africa is the common achievement of all humanity.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "The authorities liked to say that we received a balanced diet; it was indeed balanced - between the unpalatable and the inedible.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "Prison itself is a tremendous education in the need for patience and perseverance. It is above all a test of one's commitment.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "I always knew that someday I would once again feel the grass under my feet and walk in the sunshine as a free man.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "I have always believed that exercise is the key not only to physical health but to peace of mind.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "There is no easy walk to freedom anywhere, and many of us will have to pass through the valley of the shadow of death again and again before we reach the mountaintop of our desires.", Author = "Nelson Mandela" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Nelson_Mandela", Text = "I detest racialism because I regard it as a barbaric thing, whether it comes from a black man or a white man.", Author = "Nelson Mandela" },
